    public function scheduleExceptions(AuthContext $actor): array{$this->scheduleRole($actor);$own=$actor->hasAnyRole('practitioner')&&!$actor->hasAnyRole('super_admin','clinic_admin');$where=$own?' AND p.user_id=:actor':'';$params=['clinic'=>$actor->clinicId];if($own)$params['actor']=$actor->userId;$pdo=$this->database->connection();$o=$pdo->prepare("SELECT o.id,o.practitioner_id,o.location_id,o.starts_at,o.ends_at,o.override_type type,o.reason,u.display_name practitioner_name,l.name location_name,'override' kind FROM availability_overrides o JOIN practitioners p ON p.id=o.practitioner_id JOIN users u ON u.id=p.user_id JOIN locations l ON l.id=o.location_id WHERE u.clinic_id=:clinic{$where}");$o->execute($params);$t=$pdo->prepare("SELECT t.id,t.practitioner_id,NULL location_id,t.starts_at,t.ends_at,t.reason_type type,t.notes reason,u.display_name practitioner_name,NULL location_name,'time_off' kind FROM time_off t JOIN practitioners p ON p.id=t.practitioner_id JOIN users u ON u.id=p.user_id WHERE u.clinic_id=:clinic{$where}");$t->execute($params);$rows=array_merge($o->fetchAll(),$t->fetchAll());usort($rows,fn($a,$b)=>strcmp($a['starts_at'],$b['starts_at']));return $rows;}
    public function createAvailabilityOverride(AuthContext $actor,array $body,string $cid): array{$this->required($body,['practitioner_id','location_id','starts_at','ends_at','override_type']);$this->scheduleAccess($actor,(int)$body['practitioner_id']);$this->ownedLocation($actor,(int)$body['location_id']);[$start,$end]=$this->utcInterval($body,(int)$body['location_id']);if(!in_array($body['override_type'],['available','blocked'],true))throw new ApiException(422,'validation_error','Invalid override type.');$s=$this->database->connection()->prepare('INSERT INTO availability_overrides(practitioner_id,location_id,starts_at,ends_at,override_type,reason,created_by) VALUES(:p,:l,:starts,:ends,:type,:reason,:actor)');$s->execute(['p'=>(int)$body['practitioner_id'],'l'=>(int)$body['location_id'],'starts'=>$start,'ends'=>$end,'type'=>$body['override_type'],'reason'=>$this->optional($body,'reason'),'actor'=>$actor->userId]);return $this->created($actor,$cid,'availability_override',(int)$this->database->connection()->lastInsertId());}
    public function createTimeOff(AuthContext $actor,array $body,string $cid): array{$this->required($body,['practitioner_id','location_id','starts_at','ends_at','reason_type']);$this->scheduleAccess($actor,(int)$body['practitioner_id']);$this->ownedLocation($actor,(int)$body['location_id']);[$start,$end]=$this->utcInterval($body,(int)$body['location_id']);if(!in_array($body['reason_type'],['vacation','sick','personal','other'],true))throw new ApiException(422,'validation_error','Invalid reason type.');$s=$this->database->connection()->prepare('INSERT INTO time_off(practitioner_id,starts_at,ends_at,reason_type,notes,created_by) VALUES(:p,:starts,:ends,:type,:notes,:actor)');$s->execute(['p'=>(int)$body['practitioner_id'],'starts'=>$start,'ends'=>$end,'type'=>$body['reason_type'],'notes'=>$this->optional($body,'notes'),'actor'=>$actor->userId]);return $this->created($actor,$cid,'time_off',(int)$this->database->connection()->lastInsertId());}
    public function deleteScheduleException(AuthContext $actor,string $table,int $id,string $cid): array{$this->scheduleRole($actor);if(!in_array($table,['availability_overrides','time_off'],true))throw new ApiException(500,'invalid_table','Invalid schedule table.');$own=$actor->hasAnyRole('practitioner')&&!$actor->hasAnyRole('super_admin','clinic_admin');$sql="DELETE x FROM {$table} x JOIN practitioners p ON p.id=x.practitioner_id JOIN users u ON u.id=p.user_id WHERE x.id=:id AND u.clinic_id=:clinic".($own?' AND p.user_id=:actor':'');$params=['id'=>$id,'clinic'=>$actor->clinicId];if($own)$params['actor']=$actor->userId;$s=$this->database->connection()->prepare($sql);$s->execute($params);if(!$s->rowCount())throw new ApiException(404,'schedule_exception_not_found','Schedule exception not found.');$this->audit->write($actor->clinicId,$actor,$cid,'schedule_exception.delete',$table,$id);return ['deleted'=>true];}

    private function admin(AuthContext $actor): void{if(!$actor->hasAnyRole('super_admin','clinic_admin'))throw new ApiException(403,'forbidden','Administrator access is required.');}
    private function superAdmin(AuthContext $actor): void{if(!$actor->hasAnyRole('super_admin'))throw new ApiException(403,'forbidden','Super administrator access is required.');}
    private function required(array $body,array $fields): void{foreach($fields as $field)if(!array_key_exists($field,$body)||$body[$field]===''||$body[$field]===null)throw new ApiException(422,'validation_error',"{$field} is required.",[$field=>'Required']);}
    private function optional(array $body,string $field): ?string{$value=trim((string)($body[$field]??''));return $value===''?null:$value;}
    private function clinic(int $clinicId): array{$statement=$this->database->connection()->prepare('SELECT name,legal_name,email,phone FROM clinics WHERE id=:clinic');$statement->execute(['clinic'=>$clinicId]);$clinic=$statement->fetch();if(!$clinic)throw new ApiException(404,'clinic_not_found','Clinic not found.');return $clinic;}
    private function ownedLocation(AuthContext $actor,int $locationId): void{$statement=$this->database->connection()->prepare('SELECT 1 FROM locations WHERE id=:id AND clinic_id=:clinic');$statement->execute(['id'=>$locationId,'clinic'=>$actor->clinicId]);if(!$statement->fetchColumn())throw new ApiException(404,'location_not_found','Location not found.');}
    private function ownedServiceCategory(AuthContext $actor,mixed $categoryId): ?int{if($categoryId===null||$categoryId==='')return null;if(filter_var($categoryId,FILTER_VALIDATE_INT)===false||(int)$categoryId<=0)throw new ApiException(422,'validation_error','Choose a valid service category.',['category_id'=>'Invalid category']);$statement=$this->database->connection()->prepare('SELECT 1 FROM service_categories WHERE id=:id AND clinic_id=:clinic');$statement->execute(['id'=>(int)$categoryId,'clinic'=>$actor->clinicId]);if(!$statement->fetchColumn())throw new ApiException(422,'validation_error','Choose a valid service category.',['category_id'=>'Category not found']);return (int)$categoryId;}
    private function validateLocation(array $body): void{if(strlen(trim((string)$body['name']))>150)throw new ApiException(422,'validation_error','The location name is too long.',['name'=>'Maximum 150 characters']);if(!in_array((string)$body['timezone'],timezone_identifiers_list(),true))throw new ApiException(422,'validation_error','Enter a valid timezone.',['timezone'=>'Invalid timezone']);foreach(['address_line1'=>190,'address_line2'=>190,'city'=>100,'province'=>100,'postal_code'=>20,'phone'=>40] as $field=>$limit)if(strlen(trim((string)($body[$field]??'')))>$limit)throw new ApiException(422,'validation_error',"{$field} is too long.",[$field=>"Maximum {$limit} characters"]);}
    private function validateRoom(array $body): void{$name=trim((string)$body['name']);$turnover=(int)($body['turnover_minutes']??0);if($name===''||strlen($name)>100)throw new ApiException(422,'validation_error','Enter a valid room name.',['name'=>'Required; maximum 100 characters']);if(strlen(trim((string)($body['room_type']??'')))>80)throw new ApiException(422,'validation_error','The room type is too long.',['room_type'=>'Maximum 80 characters']);if($turnover<0||$turnover>240||$turnover%5!==0)throw new ApiException(422,'validation_error','Turnover time must be a 5-minute increment between 0 and 240.',['turnover_minutes'=>'Invalid turnover time']);}
    public static function durationOptions(array $body): array
    {
        $raw=$body['duration_options']??null;
        if($raw===null&&is_array($body['durations']??null))$raw=array_map(static fn($minutes)=>['minutes'=>$minutes,'price_cents'=>$body['price_cents']??null],$body['durations']);
        if(!is_array($raw)||$raw===[])throw new ApiException(422,'validation_error','Add at least one duration and price.');
        $options=[];
        foreach($raw as $option){
            if(!is_array($option)||filter_var($option['minutes']??null,FILTER_VALIDATE_INT)===false||filter_var($option['price_cents']??null,FILTER_VALIDATE_INT)===false)throw new ApiException(422,'validation_error','Each duration needs a valid time and price.');
            $minutes=(int)$option['minutes'];$price=(int)$option['price_cents'];
            if($minutes<=0||$minutes>480||$minutes%15!==0)throw new ApiException(422,'validation_error','Durations must be 15-minute increments up to 480 minutes.');
            if($price<0||$price>10000000)throw new ApiException(422,'validation_error','Each duration needs a valid price.');
            if(isset($options[$minutes]))throw new ApiException(422,'validation_error','Each duration can be listed only once.');
            $options[$minutes]=['minutes'=>$minutes,'price_cents'=>$price];
        }
        ksort($options);return array_values($options);
    }
    private function validateService(array $body,array $options): void{$this->required($body,['name']);$name=trim((string)$body['name']);if($name===''||strlen($name)>150)throw new ApiException(422,'validation_error','Enter a valid service name.');if($options===[])throw new ApiException(422,'validation_error','Add at least one duration and price.');foreach(['buffer_before_minutes','buffer_after_minutes'] as $f)if((int)($body[$f]??0)<0||(int)($body[$f]??0)%15!==0)throw new ApiException(422,'validation_error','Buffers must be non-negative 15-minute increments.');}
    private function scheduleRole(AuthContext $actor): void{if(!$actor->hasAnyRole('super_admin','clinic_admin','practitioner'))throw new ApiException(403,'forbidden','Schedule access is required.');}
    private function scheduleAccess(AuthContext $actor,int $practitionerId): void{$this->scheduleRole($actor);$sql='SELECT 1 FROM practitioners p JOIN users u ON u.id=p.user_id WHERE p.id=:p AND u.clinic_id=:clinic';$params=['p'=>$practitionerId,'clinic'=>$actor->clinicId];if($actor->hasAnyRole('practitioner')&&!$actor->hasAnyRole('super_admin','clinic_admin')){$sql.=' AND p.user_id=:actor';$params['actor']=$actor->userId;}$s=$this->database->connection()->prepare($sql);$s->execute($params);if(!$s->fetchColumn())throw new ApiException(403,'forbidden','You cannot manage that practitioner schedule.');}
    private function utcInterval(array $body,int $locationId): array{$s=$this->database->connection()->prepare('SELECT timezone FROM locations WHERE id=:id');$s->execute(['id'=>$locationId]);$timezone=$s->fetchColumn();try{$zone=new \DateTimeZone((string)$timezone);$start=new \DateTimeImmutable((string)$body['starts_at'],$zone);$end=new \DateTimeImmutable((string)$body['ends_at'],$zone);}catch(\Throwable){throw new ApiException(422,'validation_error','Enter valid local start and end times.');}if($start>=$end)throw new ApiException(422,'validation_error','Start must be before end.');$utc=new \DateTimeZone('UTC');return [$start->setTimezone($utc)->format('Y-m-d H:i:s'),$end->setTimezone($utc)->format('Y-m-d H:i:s')];}
    private function created(AuthContext $actor,string $correlationId,string $type,int $id): array{$this->audit->write($actor->clinicId,$actor,$correlationId,$type.'.create',$type,$id);return ['id'=>$id];}
